      <div class="account-order-statuses"><span class="account-order-badge <?=$statusTone((string)$o['status'])?>"><?=store_h(store_t('Order'))?> · <?=store_h($statusLabel((string)$o['status']))?></span><span class="account-order-badge <?=$statusTone((string)$o['payment_status'])?>"><?=store_h(store_t('Payment'))?> · <?=store_h($statusLabel((string)$o['payment_status']))?></span><span class="account-order-badge <?=$statusTone((string)$o['fulfillment_status'])?>"><?=store_h(store_t('Delivery'))?> · <?=store_h($statusLabel((string)$o['fulfillment_status']))?></span></div>
