      <details class="account-order-details"><summary><?=store_h(store_t('Order details'))?> <span>+</span></summary><div class="account-order-detail-grid"><div><small><?=store_h(store_t('DELIVERY ADDRESS'))?></small><strong><?=htmlspecialchars($addressLine!==''?$addressLine:store_t('Address unavailable'),ENT_QUOTES,'UTF-8')?></strong><?php if(!empty($o['customer_phone'])):?><span><?=htmlspecialchars((string)$o['customer_phone'],ENT_QUOTES,'UTF-8')?></span><?php endif;?></div><div><small><?=store_h(store_t('PAYMENT METHOD'))?></small><strong><?=htmlspecialchars((string)(($o['payment_method']??'cod')==='manual_transfer'?store_t('Bank transfer / InstaPay'):store_t('Cash on Delivery')),ENT_QUOTES,'UTF-8')?></strong><span><?=number_format((float)$o['subtotal'],2)?> <?=store_h(store_t('subtotal'))?> · <?=number_format((float)$o['discount_total'],2)?> <?=store_h(store_t('discount'))?></span></div><?php if(!empty($o['customer_note'])):?><div><small><?=store_h(store_t('YOUR NOTE'))?></small><strong><?=htmlspecialchars((string)$o['customer_note'],ENT_QUOTES,'UTF-8')?></strong></div><?php endif;?></div><?php if($history):?><div class="account-order-timeline"><small><?=store_h(store_t('STATUS HISTORY'))?></small><?php foreach(array_reverse($history) as $entry):?><div><i></i><span><strong><?=store_h($statusLabel((string)$entry['status']))?></strong><small><?=web_local_datetime($entry['created_at']??null,'—')?> · <?=store_h($statusLabel((string)($entry['fulfillment_status']??'')))?></small><?php if(trim((string)($entry['note']??''))!==''):?><em><?=htmlspecialchars((string)$entry['note'],ENT_QUOTES,'UTF-8')?></em><?php endif;?></span></div><?php endforeach;?></div><?php endif;?></details>
      <?php if($orderReturns||($returnEligible&&$hasReturnableItems)):?><details class="account-return-panel"><summary><?=store_h(store_t('Returns & refunds'))?> <span>+</span></summary><div class="account-return-body"><?php if(!$withinReturnWindow):?><p class="account-section-copy"><?=store_h(store_t('The return window for this order has ended.'))?></p><?php endif;?><?php if($orderReturns):?><div class="account-return-history"><small><?=store_h(store_t('RETURN REQUESTS'))?></small><?php foreach($orderReturns as $return):?><article><div><strong><?=store_h(store_t('Return'))?> #<?=(int)$return['id']?></strong><span><?=web_local_datetime($return['requested_at']??null,'—')?> · <?=store_h($statusLabel((string)$return['status']))?></span></div><?php if((float)$return['refund_amount']>0):?><b><?=number_format((float)$return['refund_amount'],2)?> <?=htmlspecialchars((string)$o['currency'],ENT_QUOTES,'UTF-8')?> <?=store_h(store_t('refunded'))?></b><?php endif;?><?php if((string)$return['status']==='requested'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="cancel_return"><input type="hidden" name="return_id" value="<?=(int)$return['id']?>"><button class="app-button secondary" type="submit" data-confirm="<?=store_h(store_t('Cancel this return request?'))?>"><?=store_h(store_t('Cancel request'))?></button></form><?php endif;?></article><?php endforeach;?></div><?php endif;?><?php if($returnEligible&&$hasReturnableItems):?><form method="post" class="account-return-form"><?=csrf_field()?><input type="hidden" name="action" value="request_return"><input type="hidden" name="order_id" value="<?=$oid?>"><div><small><?=store_h(store_t('REQUEST A RETURN'))?></small><p><?=store_h(store_t('Select the quantities to request a return. Sending a request does not issue a refund or change inventory.'))?></p></div><div class="account-return-items"><?php foreach($items as $item):$remainingQty=max(0,(int)$item['quantity']-(int)($returnUsedByItem[(int)$item['id']]??0));?><label><span><strong><?=htmlspecialchars((string)$item['product_name'],ENT_QUOTES,'UTF-8')?></strong><small><?=htmlspecialchars((string)($item['variant_label']??''),ENT_QUOTES,'UTF-8')?> · <?=$remainingQty?> <?=store_h(store_t('of'))?> <?=(int)$item['quantity']?> <?=store_h(store_t('returnable'))?></small></span><select name="return_qty[<?=(int)$item['id']?>]" aria-label="<?=store_h(store_t('Return quantity for'))?> <?=htmlspecialchars((string)$item['product_name'],ENT_QUOTES,'UTF-8')?>" <?=$remainingQty<=0?'disabled':''?>><?php for($qty=0;$qty<=$remainingQty;$qty++):?><option value="<?=$qty?>"><?=$qty?></option><?php endfor;?></select></label><?php endforeach;?></div><label class="account-return-field"><span><?=store_h(store_t('Reason'))?></span><input name="reason" maxlength="500" required placeholder="<?=store_h(store_t('e.g. Unopened item no longer needed'))?>"></label><label class="account-return-field"><span><?=store_h(store_t('Additional note'))?> <small><?=store_h(store_t('(optional)'))?></small></span><textarea name="customer_note" rows="2" maxlength="1000" placeholder="<?=store_h(store_t('Add useful details for the store team'))?>"></textarea></label><button class="app-button primary" type="submit"><?=store_h(store_t('SUBMIT RETURN REQUEST'))?></button></form><?php endif;?></div></details><?php endif;?>
      <footer class="account-order-footer"><a href="<?=htmlspecialchars(route_url('support.php'),ENT_QUOTES,'UTF-8')?>"><?=store_h(store_t('Need help with this order? Contact support →'))?></a></footer>
    </article>
  <?php endforeach;?></div><?php endif;?>
</section>
